let collection = ['b5c18ef7dcb9deac80b99470', 'fff5ebdeedf0f4c7abb2b8a3']
// get all palettes
export const getPalettes = () => palettes

//add a new palette
export const addOne = (item) => {
    const itemId = item.myColors.reduce((str, color) => str += color.substring(1), '')
    if (palettes.indexOf(({ id }) => id === itemId) === -1)
        palettes.push(item)
}

//get my collection
export const getCollection = () => {
    return palettes.filter(({ id }) => collection.includes(id))
}

// add to my collection
export const addToCollection = ({ id }) => {
    if (!collection.includes(id))
        collection.push(id)
}

//remove from my collection
export const removeFromCollection = ({ id }) => {
    if (collection.includes(id)) {
        const index = collection.indexOf(id)
        collection = collection.splice(index, 1)
    }
}